#include "pixel_viewport_view.hpp"
namespace x2dui {
static void drop(const MenuProfile&p,AbiArray&a,unsigned element){if(a.owner){auto*r=static_cast<int*>(a.owner);if(__atomic_load_n(r,__ATOMIC_RELAXED)>=0&&__atomic_sub_fetch(r,1,__ATOMIC_ACQ_REL)==0)p.deallocate(a.owner,element,8);}}
static bool number(const MenuProfile&p,void*o,const char*name,unsigned&out,unsigned limit=32768){auto v=p.property(o,name);bool ok=false;double n=p.number(&v,&ok);p.variant_destroy(&v);if(!ok||n<0||n>limit||n!=static_cast<unsigned>(n))return false;out=static_cast<unsigned>(n);return true;}
static ProtocolText source(const MenuProfile&p,void*o){auto v=p.property(o,"source");auto a=p.string(&v);ProtocolText s;if(a.size<0||a.size>128||(!a.data&&a.size))s.invalidate();else for(std::ptrdiff_t i=0;i<a.size;i++){auto c=static_cast<char16_t*>(a.data)[i];if(c>127){s.invalidate();break;}s+=char(c);}drop(p,a,2);p.variant_destroy(&v);return s;}
void PixelViewportView::event(void*p,Event e,double){if(e==Event::Destroy)static_cast<PixelViewportView*>(p)->root=nullptr;}
void PixelViewportView::close(){if(borrowed_){statusLease.close();root=nullptr;borrowed_=false;return;}if(root){auto*p=root;root=nullptr;api.destroy(api.context,p);}}
bool PixelViewportView::borrow(void*original,BindingProfile b,SignalProfile g,unsigned texture){if(root||!original||!texture||texture>32768||((23326+texture-1)/texture)*((17498+texture-1)/texture)>256||!stock.cast(stock.meta_item,original))return false;if(!statusLease.acquire(stock,b,g,original,u"status"))return false;root=original;texture_=texture;borrowed_=true;core_=PixelViewportCore{};return true;}
bool PixelViewportView::observe_existing(ProtocolBytes src,unsigned w,unsigned h,uint64_t now){if(!borrowed_||!statusLease.alive())return false;if(!PixelViewportCore::valid_source(src,w,h)){close();return false;}core_.adopt(src,w,h,texture_,now);if(!core_.count())return false;bool seen[256]{};unsigned nodes=0;void*first=nullptr;if(!scan(root,nodes,seen,first,now,true))return false;for(unsigned i=0;i<core_.count();i++)if(!seen[i])core_.observe(core_.generation(),i,3,false,0,now);return statusLease.number(static_cast<unsigned>(core_.status()));}
bool PixelViewportView::attach(void*parent){if(root||!parent||!stock.meta_image)return false;core_=PixelViewportCore{};root=stock_create(stock,StockKind::TiledImage,parent,parent);if(!root)return false;if(!api.listen(api.context,root,Event::Destroy,event,this,release)||!number(menu,root,"width",texture_)||!texture_||((23326+texture_-1)/texture_)*((17498+texture_-1)/texture_)>256||!stock_override_number(stock,root,u"status",0)){close();return false;}api.name(api.context,root,"PixelJpegViewportNative");return true;}
bool PixelViewportView::set(ProtocolBytes src,unsigned w,unsigned h,unsigned texture,uint64_t now){if(borrowed_||!root||texture!=texture_)return false;bool changed=core_.set(src,w,h,texture,now);if(changed){if(!stock_set_text(stock,root,"source",u"")||!stock_override_number(stock,root,u"status",0))return false;bool valid=PixelViewportCore::valid_source(src,w,h);if(!stock_set_size(stock,root,"imageSize",valid?int(w):1,valid?int(h):1))return false;api.rect(api.context,root,0,0,valid?w:0,valid?h:0);}return true;}
// Enumerate fresh children rather than retaining image pointers across source
// changes. Each image must match exactly one expected crop URL in this generation.
bool PixelViewportView::scan(void*node,unsigned&nodes,bool*seen,void*&first,uint64_t now,bool observe,unsigned depth)const{
 if(!node||depth>64||++nodes>4096)return false;auto children=menu.children(node);if(children.size<0||children.size>4096||(!children.data&&children.size)){drop(menu,children,8);return false;}auto**items=static_cast<void**>(children.data);void*image=nullptr,*lut=nullptr;unsigned images=0;
 for(std::ptrdiff_t i=0;i<children.size;i++)if(stock.cast(stock.meta_image,items[i])){++images;unsigned used;if(number(menu,items[i],"used",used,1))lut=items[i];else image=items[i];}
 bool ok=true;if(images){if(images!=2||!image||!lut)ok=false;else{auto s=source(menu,image);unsigned index=core_.count();for(unsigned i=0;i<core_.count();++i)if(s==core_.tile_source(i)){index=i;break;}if(index==core_.count()||seen[index])ok=false;else{seen[index]=true;if(index==0)first=image;unsigned im=0,ls=0,used=0;bool read=number(menu,image,"status",im,3)&&number(menu,lut,"status",ls,3)&&number(menu,lut,"used",used,1);if(observe)const_cast<PixelViewportCore&>(core_).observe(core_.generation(),index,read?im:3,used!=0,read?ls:0,now);}}}
 else for(std::ptrdiff_t i=0;i<children.size&&ok;i++)ok=scan(items[i],nodes,seen,first,now,observe,depth+1);drop(menu,children,8);return ok;
}
bool PixelViewportView::tick(uint64_t now,bool over){if(borrowed_||!root)return false;if(core_.tick(now)){UiText s;for(char c:core_.decode_source())s+=char16_t(static_cast<unsigned char>(c));if(!s.valid()||!stock_set_text(stock,root,"source",s.c_str()))return false;}if(!stock_set_bool(stock,root,"overExposureRunning",over))return false;
 if(core_.count()){bool seen[256]{};unsigned nodes=0;void*first=nullptr;if(!scan(root,nodes,seen,first,now,true))return false;for(unsigned i=0;i<core_.count();i++)if(!seen[i])core_.observe(core_.generation(),i,3,false,0,now);}
 return stock_override_number(stock,root,u"status",static_cast<unsigned>(core_.status()));
}
void*PixelViewportView::active_image()const{if(!item()||!core_.count())return nullptr;bool seen[256]{};unsigned nodes=0;void*first=nullptr;return scan(root,nodes,seen,first,0,false)?first:nullptr;}
}
